from dataclasses import dataclass, field

from src import (
    MandelbrotConfig,
    MandelbrotCalculator,
    NativeCalculator,
    NumpyCalculator,
    NumbaCalculator,
    MultiprocessCalculator,
)

# Registry of available calculators by name
CALCULATOR_REGISTRY: dict[str, type[MandelbrotCalculator]] = {
    "native": NativeCalculator,
    "numpy": NumpyCalculator,
    "numba": NumbaCalculator,
    "multiprocess": MultiprocessCalculator,
}


@dataclass
class BenchmarkConfig:
    # Mandelbrot set parameters
    mb_config: MandelbrotConfig = field(default_factory=MandelbrotConfig)

    # Benchmark-specific parameters
    calculators: list[str] = field(default_factory=lambda: ["native", "numpy", "numba", "multiprocess"])
    resolutions: list[int] = field(default_factory=lambda: [64, 128, 256, 512, 1024])
    num_runs: int = 3  # Number of runs per (calculator, resolution) for averaging
    warmup_runs: int = 1  # Warmup runs (not counted in timing)
    output_dir: str = "results"

    def get_calculator_classes(self) -> list[type[MandelbrotCalculator]]:
        """Resolve calculator names to classes."""
        classes = []
        for name in self.calculators:
            if name not in CALCULATOR_REGISTRY:
                raise ValueError(f"Unknown calculator: '{name}'. Available: {list(CALCULATOR_REGISTRY.keys())}")
            classes.append(CALCULATOR_REGISTRY[name])
        return classes
